def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_defects = opp.count('D')

    if n >= 2 and opp_defects == n:
        return 'D'

    if n >= 15 and opp_defects * 2 >= n:
        return 'D'

    if n >= 10:
        recent = opp[-10:]
        if recent.count('D') >= 6:
            return 'D'

    if opp[-1] == 'D':
        if my[-1] == 'D':
            if n >= 6 and opp[-6:].count('D') >= 3:
                return 'D'
            return 'C'
        return 'D'

    if my[-1] == 'D':
        return 'C'

    return 'C'
